import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:fl_chart/fl_chart.dart';
import '../../core/providers/machinery_provider.dart';
import '../../core/theme.dart';

class MachineryScreen extends ConsumerStatefulWidget {
  const MachineryScreen({super.key});

  @override
  ConsumerState<MachineryScreen> createState() => _MachineryScreenState();
}

class _MachineryScreenState extends ConsumerState<MachineryScreen> {
  final _searchController = TextEditingController();

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      ref.read(machineryProvider.notifier).fetchMachinery();
    });
  }

  @override
  void dispose() {
    _searchController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final mac = ref.watch(machineryProvider);
    final machineryList = mac.machinery;

    // Use mock data if empty for UI demonstration
    final List<dynamic> displayMachinery = machineryList.isNotEmpty ? machineryList : [
      {'name': 'Excavator 01', 'model_number': 'CAT 336', 'status': 'Active', 'total_hours_run': 125.4, 'fuel': 78, 'location': 'Site A', 'id_tag': 'ID: E-001'},
      {'name': 'Bulldozer 03', 'model_number': 'Komatsu D85', 'status': 'Active', 'total_hours_run': 94.1, 'fuel': 52, 'location': 'Site B', 'id_tag': 'ID: B-003'},
      {'name': 'Crane 02', 'model_number': 'Liebherr LTM', 'status': 'Maintenance', 'total_hours_run': 125.4, 'fuel': 78, 'location': 'Site A', 'id_tag': 'ID: C-002'},
    ];

    return Scaffold(
      backgroundColor: CivilTheme.background,
      body: LayoutBuilder(
        builder: (context, constraints) {
          final isMobile = constraints.maxWidth < 900;
          return Stack(
            children: [
              // Mock background image effect (gradient for now)
              Container(
                decoration: const BoxDecoration(
                  gradient: LinearGradient(
                    colors: [Color(0xFF222B38), Color(0xFF161F2E)],
                    begin: Alignment.topCenter,
                    end: Alignment.bottomCenter,
                  ),
                ),
              ),
              Center(
                child: ConstrainedBox(
                  constraints: BoxConstraints(maxWidth: isMobile ? 600 : 1200),
                  child: Column(
                    children: [
                      SafeArea(
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),
                          child: Column(
                            children: [
                              Row(
                                children: [
                                  Container(
                                    padding: const EdgeInsets.all(8),
                                    decoration: BoxDecoration(color: CivilTheme.surface.withOpacity(0.5), borderRadius: BorderRadius.circular(12)),
                                    child: const Icon(Icons.menu, color: CivilTheme.textSecondary, size: 20),
                                  ),
                                  const Spacer(),
                                  const Text('Fleet Machinery', style: TextStyle(color: CivilTheme.textPrimary, fontSize: 18, fontWeight: FontWeight.bold)),
                                  const Spacer(),
                                  const CircleAvatar(radius: 14, backgroundImage: NetworkImage('https://i.pravatar.cc/150?img=11')),
                                  const SizedBox(width: 8),
                                  Container(
                                    padding: const EdgeInsets.all(8),
                                    decoration: BoxDecoration(color: CivilTheme.surface.withOpacity(0.5), borderRadius: BorderRadius.circular(12)),
                                    child: const Icon(Icons.notifications_none, color: CivilTheme.textSecondary, size: 20),
                                  ),
                                ],
                              ),
                              const SizedBox(height: 20),
                              Row(
                                children: [
                                  Expanded(
                                    child: Container(
                                      height: 48,
                                      padding: const EdgeInsets.symmetric(horizontal: 16),
                                      decoration: BoxDecoration(
                                        color: CivilTheme.surface.withOpacity(0.6),
                                        borderRadius: BorderRadius.circular(12),
                                        border: Border.all(color: CivilTheme.border),
                                      ),
                                      child: Row(
                                        children: [
                                          const Icon(Icons.search, color: CivilTheme.textSecondary, size: 20),
                                          const SizedBox(width: 12),
                                          Expanded(
                                            child: TextField(
                                              controller: _searchController,
                                              style: const TextStyle(color: CivilTheme.textPrimary, fontSize: 14),
                                              decoration: const InputDecoration(
                                                hintText: 'Search fleet, status, ID...',
                                                hintStyle: TextStyle(color: CivilTheme.textSecondary),
                                                border: InputBorder.none,
                                                isDense: true,
                                              ),
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 12),
                                  Container(
                                    height: 48, width: 48,
                                    decoration: BoxDecoration(color: CivilTheme.surface.withOpacity(0.6), borderRadius: BorderRadius.circular(12), border: Border.all(color: CivilTheme.border)),
                                    child: const Icon(Icons.filter_list, color: CivilTheme.textSecondary),
                                  ),
                                  const SizedBox(width: 12),
                                  Container(
                                    height: 48, width: 48,
                                    decoration: BoxDecoration(color: CivilTheme.surface.withOpacity(0.6), borderRadius: BorderRadius.circular(12), border: Border.all(color: CivilTheme.border)),
                                    child: const Icon(Icons.grid_view, color: CivilTheme.textSecondary),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ),
                      Expanded(
                        child: isMobile 
                            ? ListView.separated(
                                padding: const EdgeInsets.all(20),
                                itemCount: displayMachinery.length,
                                separatorBuilder: (context, index) => const SizedBox(height: 20),
                                itemBuilder: (context, index) => _buildMachineryCard(displayMachinery[index], showChart: index == 0),
                              )
                            : GridView.builder(
                                padding: const EdgeInsets.all(20),
                                gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                                  maxCrossAxisExtent: 450,
                                  mainAxisSpacing: 20,
                                  crossAxisSpacing: 20,
                                  childAspectRatio: 1.3,
                                ),
                                itemCount: displayMachinery.length,
                                itemBuilder: (context, index) => _buildMachineryCard(displayMachinery[index], showChart: index == 0),
                              ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildMachineryCard(Map<String, dynamic> mac, {bool showChart = false}) {
    final status = mac['status']?.toString().toUpperCase() ?? 'ACTIVE';
    final isActive = status == 'ACTIVE';
    final glowColor = isActive ? Colors.greenAccent : Colors.amber;

    return Container(
      decoration: BoxDecoration(
        color: CivilTheme.surface.withOpacity(0.6),
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: glowColor.withOpacity(0.4), width: 1.5),
        boxShadow: [BoxShadow(color: glowColor.withOpacity(0.05), blurRadius: 20, spreadRadius: 5)],
      ),
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 50, height: 50,
                decoration: BoxDecoration(
                  color: CivilTheme.background,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: CivilTheme.border),
                ),
                child: const Icon(Icons.precision_manufacturing, color: Colors.amber, size: 28), // Mock icon
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text('${mac['name']} | ${mac['model_number']}', style: const TextStyle(color: CivilTheme.textPrimary, fontSize: 15, fontWeight: FontWeight.bold)),
                    const SizedBox(height: 4),
                    Text(mac['id_tag'] ?? 'ID: Unknown', style: const TextStyle(color: CivilTheme.textSecondary, fontSize: 12)),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: isActive ? glowColor.withOpacity(0.1) : Colors.transparent,
                  border: Border.all(color: glowColor),
                  borderRadius: BorderRadius.circular(16),
                ),
                child: Text(
                  status,
                  style: TextStyle(color: glowColor, fontSize: 10, fontWeight: FontWeight.bold),
                ),
              ),
            ],
          ),
          if (showChart) ...[
            const SizedBox(height: 20),
            SizedBox(
              height: 40,
              child: Stack(
                children: [
                  LineChart(
                    LineChartData(
                      gridData: const FlGridData(show: false),
                      titlesData: const FlTitlesData(show: false),
                      borderData: FlBorderData(show: false),
                      minX: 0, maxX: 6, minY: 0, maxY: 10,
                      lineBarsData: [
                        LineChartBarData(
                          spots: const [
                            FlSpot(0, 3), FlSpot(1, 4), FlSpot(2, 3), FlSpot(3, 7), FlSpot(4, 4), FlSpot(5, 8), FlSpot(6, 5),
                          ],
                          isCurved: true,
                          color: Colors.greenAccent,
                          barWidth: 2,
                          isStrokeCapRound: true,
                          dotData: const FlDotData(show: false),
                          belowBarData: BarAreaData(
                            show: true,
                            color: Colors.greenAccent.withOpacity(0.1),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Positioned(
                    right: 0, top: 0,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: const [
                        Text('Usage', style: TextStyle(color: CivilTheme.textSecondary, fontSize: 10)),
                        Text('48hr', style: TextStyle(color: CivilTheme.textPrimary, fontSize: 12, fontWeight: FontWeight.bold)),
                      ],
                    ),
                  )
                ],
              ),
            ),
          ],
          const Spacer(),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              _buildDataCol('Hours:', '${mac['total_hours_run'] ?? 0} hr'),
              _buildDataCol('Fuel:', '${mac['fuel'] ?? 0}%'),
              _buildDataCol('Location:', '${mac['location'] ?? 'Unknown'}'),
            ],
          ),
          const SizedBox(height: 16),
          Row(
            children: [
              Container(width: 12, height: 12, decoration: BoxDecoration(color: isActive ? Colors.green : Colors.grey, shape: BoxShape.circle)),
              const SizedBox(width: 4),
              Container(width: 6, height: 6, decoration: BoxDecoration(color: isActive ? Colors.grey : Colors.amber, shape: BoxShape.circle)),
              const SizedBox(width: 4),
              Container(width: 6, height: 6, decoration: const BoxDecoration(color: Colors.grey, shape: BoxShape.circle)),
              const Spacer(),
              _buildActionButton('Details'),
              const SizedBox(width: 8),
              _buildActionButton('Maintain'),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildDataCol(String label, String value) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(label, style: const TextStyle(color: CivilTheme.textSecondary, fontSize: 11)),
        const SizedBox(height: 4),
        Text(value, style: const TextStyle(color: CivilTheme.textPrimary, fontSize: 16, fontWeight: FontWeight.bold)),
      ],
    );
  }

  Widget _buildActionButton(String label) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      decoration: BoxDecoration(
        color: CivilTheme.surface.withOpacity(0.8),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: CivilTheme.border),
      ),
      child: Text(label, style: const TextStyle(color: CivilTheme.textPrimary, fontSize: 12)),
    );
  }
}
